def generate_rotating_humanoid_frames(size, num_frames=72):
    """
    Generates frames for a rotating 3D wireframe humanoid model.
    """
    frames = []
    
    # Define the joints of a simple humanoid stick figure. Y is the vertical axis.
    # Y-coordinates are inverted to make the model right-side up on the canvas.
    points = np.array([
        [0, -2.5, 0],   # 0: Head top
        [0, -1.8, 0],   # 1: Neck
        [-1.2, -1.5, 0],# 2: Left Shoulder
        [1.2, -1.5, 0], # 3: Right Shoulder
        [-1.2, 0, 0],   # 4: Left Hand
        [1.2, 0, 0],    # 5: Right Hand
        [0, 1, 0],      # 6: Hip center
        [-0.8, 1.2, 0], # 7: Left Hip
        [0.8, 1.2, 0],  # 8: Right Hip
        [-0.8, 3, 0],   # 9: Left Foot
        [0.8, 3, 0]     # 10: Right Foot
    ])

    # Define the bones (edges) connecting the joints
    edges = [
        (1, 2), (1, 3), (2, 4), (3, 5), # Arms
        (1, 6), # Torso
        (6, 7), (6, 8), # Hips
        (7, 9), (8, 10) # Legs
    ]
    
    head_center_index = 0
    head_radius = 0.7 # in 3D space units

    canvas_size = int(size * 8) # Make canvas large enough for the model
    center_offset = canvas_size / 2

    for i in range(num_frames):
        angle_y = (i * 2 * np.pi / num_frames)
        
        # Define rotation matrix for a simple turntable rotation around the Y-axis
        rot_y = np.array([[np.cos(angle_y), 0, np.sin(angle_y)],
                          [0, 1, 0],
                          [-np.sin(angle_y), 0, np.cos(angle_y)]])
        
        # Rotate points
        rotated_points = np.dot(points, rot_y)
        
        # Project 3D points to 2D for rendering
        projected_points = (rotated_points[:, :2] * size) + center_offset
        
        # Create a blank image with a transparent background
        image = Image.new("RGBA", (canvas_size, canvas_size), (0, 0, 0, 0))
        draw = ImageDraw.Draw(image)
        
        # Draw the bones
        line_color = "#AFEEEE" # Pale Turquoise, good for a hologram effect
        for edge in edges:
            p1 = projected_points[edge[0]]
            p2 = projected_points[edge[1]]
            draw.line((p1[0], p1[1], p2[0], p2[1]), fill=line_color, width=3)
            
        # Draw the head as a circle
        head_pos_2d = projected_points[head_center_index]
        r = head_radius * size 
        draw.ellipse((head_pos_2d[0]-r, head_pos_2d[1]-r, head_pos_2d[0]+r, head_pos_2d[1]+r), outline=line_color, width=3)
            
        frames.append(ImageTk.PhotoImage(image))
        
    return frames

# Load all the frames for the rotating model animation
model_frames = generate_rotating_humanoid_frames(25) # Size 25
