# Create the image object on the canvas that will be animated
model_image_obj = canvas.create_image(
    479.0,
    278.0,
    image=model_frames[model_frame_index]
)

def update_model_animation():
    """
    Cycles through the pre-loaded frames to animate the player model.
    """
    global model_frame_index
    # Move to the next frame, looping back to the start
    model_frame_index = (model_frame_index + 1) % len(model_frames)
    # Update the canvas item with the new frame
    canvas.itemconfig(model_image_obj, image=model_frames[model_frame_index])
    # Schedule the next frame update (50ms delay for ~20 FPS)
    window.after(50, update_model_animation)

# Start the animation loop
update_model_animation()


